var issues = new System.Collections.Generic.List<string>(); int checkedObjects = 0;
System.Action<UnityEngine.Object> inspect = obj => {
 if (!obj) return;
 checkedObjects++;
 var serialized = new UnityEditor.SerializedObject(obj);
 var property = serialized.GetIterator();
 while (property.Next(true)) if (property.propertyType == UnityEditor.SerializedPropertyType.ObjectReference && property.objectReferenceValue == null && property.objectReferenceInstanceIDValue != 0) issues.Add(obj.name + ":" + property.propertyPath);
};
foreach (var guid in UnityEditor.AssetDatabase.FindAssets("", new[] { "Assets" })) {
 var path = UnityEditor.AssetDatabase.GUIDToAssetPath(guid);
 if (path.EndsWith(".prefab")) {
  var prefab = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(path);
  foreach (var transform in prefab.GetComponentsInChildren<UnityEngine.Transform>(true)) {
   if (UnityEditor.GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(transform.gameObject) > 0) issues.Add(path + ":missing script");
   foreach (var component in transform.GetComponents<UnityEngine.Component>()) inspect(component);
  }
 } else if (path.EndsWith(".asset") || path.EndsWith(".mat")) {
  foreach (var asset in UnityEditor.AssetDatabase.LoadAllAssetsAtPath(path)) inspect(asset);
 }
}
foreach (var buildScene in UnityEditor.EditorBuildSettings.scenes) {
 var scene = UnityEditor.SceneManagement.EditorSceneManager.OpenScene(buildScene.path);
 foreach (var root in scene.GetRootGameObjects()) foreach (var transform in root.GetComponentsInChildren<UnityEngine.Transform>(true)) {
  if (UnityEditor.GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(transform.gameObject) > 0) issues.Add(buildScene.path + ":missing script");
  foreach (var component in transform.GetComponents<UnityEngine.Component>()) inspect(component);
 }
}
UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Application/Title.unity");
return new { checkedObjects, issues = issues.ToArray(), passed = issues.Count == 0 };
